"""Apply explicit historical encoder corrections to source-generated bytes.

These records contain binary differences recovered from the historical release;
they are NOT evidence that the old encoder algorithm was fully recovered. The
generator must first produce the exact, hash-bound intermediate. No fallback to
release files, fuzzy patching, or replacement of an entire missing input exists.
"""
import bz2
import hashlib
import struct


def sha(data):
    return hashlib.sha256(data).hexdigest()


def signed(data):
    value = int.from_bytes(data, 'little')
    return -(value & ((1 << 63) - 1)) if value >> 63 else value


def apply(data, patch, record):
    if sha(data) != record['generated_sha256']:
        raise ValueError('Historical encoder intermediate changed: ' + record['identity'])
    if sha(patch) != record['patch_sha256']:
        raise ValueError('Historical correction identity changed')
    if patch[:8] != b'BSDIFF40' or len(patch) < 32:
        raise ValueError('Invalid historical correction')
    nc, nd, size = (signed(patch[p:p+8]) for p in (8, 16, 24))
    if min(nc, nd, size) < 0 or size != record['output_bytes'] or size > 64*1024*1024:
        raise ValueError('Historical correction bounds')
    if 32+nc+nd > len(patch):
        raise ValueError('Truncated historical correction')
    controls = bz2.decompress(patch[32:32+nc])
    differences = bz2.decompress(patch[32+nc:32+nc+nd])
    extra = bz2.decompress(patch[32+nc+nd:])
    output = bytearray()
    old = dp = ep = 0
    if len(controls) % 24:
        raise ValueError('Invalid historical control stream')
    for p in range(0, len(controls), 24):
        x, y, z = (signed(controls[q:q+8]) for q in (p, p+8, p+16))
        if min(x,y) < 0 or len(output)+x+y > size or dp+x > len(differences) or ep+y > len(extra):
            raise ValueError('Historical control exceeds output')
        output.extend((differences[dp+i]+(data[old+i] if 0 <= old+i < len(data) else 0)) & 255 for i in range(x))
        output.extend(extra[ep:ep+y])
        old += x+z
        dp += x
        ep += y
    if len(output) != size or dp != len(differences) or ep != len(extra) or sha(output) != record['output_sha256']:
        raise ValueError('Historical corrected output identity mismatch')
    return bytes(output)
